import React, { useState, useEffect, useCallback } from "react";
import axios from "axios";
import styled from "styled-components";
import { useParams } from "react-router-dom";
import Card from "../components/Card";

const EmployeePage = () => {
  const { id } = useParams();
  const [employeeRole, setEmployeeRole] = useState("driver");
  const [filteredEmployees, setFilteredEmployees] = useState([]);
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [isUpdateFormVisible, setUpdateFormVisible] = useState(false);
  const [salaryDetails, setSalaryDetails] = useState({ startDate: "", endDate: "", expense: "", daysWorked: 0 });
  const [detailsTable, setDetailsTable] = useState([]);

  const fetchEmployeesByRole = useCallback(async (role) => {
    try {
      const response = await axios.get(
        `http://localhost:5001/api/employee/employeesByRole/${id}/${role}`
      );
      setFilteredEmployees(response.data);
    } catch (error) {
      console.error("Error fetching employees:", error);
    }
  }, [id]);

  const handleEmployeeClick = async (phone) => {
    try {
      const response = await axios.get(`http://localhost:5001/api/employee/${phone}`);
      setSelectedEmployee(response.data);
      setUpdateFormVisible(true);
    } catch (error) {
      console.error("Error fetching employee details:", error);
      alert("Error fetching employee details");
    }
  };

  const handleDeleteEmployee = async (phone) => {
    try {
      await axios.delete(`http://localhost:5001/api/employee/${phone}`);
      alert("Employee deleted successfully");
      fetchEmployeesByRole(employeeRole);
    } catch (error) {
      console.error("Error deleting employee:", error);
      alert("Error deleting employee");
    }
  };

  const handleUpdateSalary = async () => {
    if (!selectedEmployee) {
      alert("Please select an employee first");
      return;
    }

    try {
      const { startDate, endDate, expense, daysWorked } = salaryDetails;
      await axios.put(`http://localhost:5001/api/employee/updateSalary/${selectedEmployee.phone}`, {
        startDate,
        endDate,
        expense,
        daysWorked,
      });
      alert("Salary details updated successfully");
      setUpdateFormVisible(false);
      fetchEmployeesByRole(employeeRole);
    } catch (error) {
      console.error("Error updating salary details:", error);
      alert("Error updating salary details");
    }
  };

  const handleViewDetails = async (phone) => {
    try {
      const response = await axios.get(`http://localhost:5001/api/salary/salaryDetails/${phone}`);
      setDetailsTable(response.data);
    } catch (error) {
      console.error('Error fetching salary details:', error);
      alert('Error fetching salary details');
    }
  };

  const handleDateChange = () => {
    const startDate = new Date(salaryDetails.startDate);
    const endDate = new Date(salaryDetails.endDate);
    const timeDiff = Math.abs(endDate - startDate);
    const daysWorked = Math.ceil(timeDiff / (1000 * 3600 * 24)) + 1;
    setSalaryDetails((prevDetails) => ({
      ...prevDetails,
      daysWorked,
    }));
  };

  useEffect(() => {
    fetchEmployeesByRole(employeeRole);
  }, [employeeRole, id, fetchEmployeesByRole]);

  return (
    <Container>
      <Header>
        <LorryTitle>Lorry {id}</LorryTitle>
      </Header>

      <EmployeeRoles>
        <RoleTabs>
          {['driver', 'driller', 'manager', 'worker'].map((role) => (
            <Tab key={role} onClick={() => setEmployeeRole(role)}>
              {role.charAt(0).toUpperCase() + role.slice(1)}s
            </Tab>
          ))}
        </RoleTabs>

        <EmployeeList>
          {filteredEmployees.map((employee) => (
            <EmployeeItem key={employee.phone}>
              <div onClick={() => handleEmployeeClick(employee.phone)}>
                {employee.name} ({employee.phone})
              </div>
              <Button onClick={() => handleViewDetails(employee.phone)}>Details</Button>
              <Button onClick={() => setUpdateFormVisible(true)}>Update</Button>
              <Button onClick={() => handleDeleteEmployee(employee.phone)}>Delete</Button>
            </EmployeeItem>
          ))}
        </EmployeeList>
      </EmployeeRoles>

      {isUpdateFormVisible && (
        <Form>
          <Input
            type="date"
            placeholder="Start Date"
            value={salaryDetails.startDate}
            onChange={(e) => {
              setSalaryDetails({ ...salaryDetails, startDate: e.target.value });
              handleDateChange();
            }}
          />
          <Input
            type="date"
            placeholder="End Date"
            value={salaryDetails.endDate}
            onChange={(e) => {
              setSalaryDetails({ ...salaryDetails, endDate: e.target.value });
              handleDateChange();
            }}
          />
          <Input
            type="number"
            placeholder="Expense"
            value={salaryDetails.expense}
            onChange={(e) => setSalaryDetails({ ...salaryDetails, expense: e.target.value })}
          />
          <Button onClick={handleUpdateSalary}>Update Salary</Button>
        </Form>
      )}

      {detailsTable.length > 0 && (
        <DetailsTable>
          <thead>
            <tr>
              <th>Name</th>
              <th>Phone</th>
              <th>Expense</th>
              <th>Date</th>
              <th>Days Worked</th>
            </tr>
          </thead>
          <tbody>
            {detailsTable.map((detail, index) => (
              <tr key={index}>
                <td>{detail.name}</td>
                <td>{detail.phone}</td>
                <td>{detail.expense}</td>
                <td>{detail.date}</td>
                <td>{detail.daysWorked}</td>
              </tr>
            ))}
          </tbody>
        </DetailsTable>
      )}
    </Container>
  );
};

export default EmployeePage;


// Styled Components
const Container = styled.div`
  padding: 20px;
  background-color: #f4f7fc;
`;

const Header = styled.header`
  display: flex;
  justify-content: center;
  padding: 20px;
  background-color: #ffffff;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const LorryTitle = styled.h1`
  font-size: 2rem;
  font-weight: bold;
`;

const Button = styled.button`
  padding: 10px 20px;
  background-color: #4caf50;
  color: white;
  font-size: 1.1rem;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  margin-top: 20px;

  &:hover {
    background-color: #45a049;
  }
`;

const Form = styled.div`
  background-color: #ffffff;
  padding: 20px;
  margin-top: 20px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const Input = styled.input`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const Select = styled.select`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const EmployeeRoles = styled.div`
  margin-top: 30px;
`;

const RoleTabs = styled.div`
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
`;

const Tab = styled.div`
  padding: 10px 20px;
  margin: 0 10px;
  cursor: pointer;
  background-color: #f0f0f0;
  border-radius: 5px;
  font-weight: bold;

  &:hover {
    background-color: #ddd;
  }
`;

const EmployeeList = styled.ul`
  list-style-type: none;
  padding: 0;
`;

const EmployeeItem = styled.li`
  font-size: 1rem;
  padding: 5px;
  border-bottom: 1px solid #ccc;
  cursor: pointer;

  &:hover {
    background-color: #f4f4f9;
  }
`;

const EmployeeDetails = styled.div`
  background-color: #fff;
  padding: 20px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  margin-top: 20px;
`;

const DetailsTable = styled.table`
  width: 100%;
  border-collapse: collapse;
  margin-top: 20px;

  th,
  td {
    border: 1px solid #ddd;
    padding: 8px;
    text-align: left;
  }

  th {
    background-color: #f4f4f4;
    font-weight: bold;
  }
`;

const CardGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 20px;
`;
